#!/usr/bin/env python3

"""Report account balances from a ledger file."""

import sys


def to_cents(amount):
    whole, _, frac = amount.partition(".")
    return int(whole) * 100 + int(frac or "0")


def format_cents(cents):
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def read_ledger(path):
    with open(path, "rb") as f:
        data = f.read()
    return data.decode("utf-8", errors="surrogateescape").split("\n")


def emit(lines):
    out = "".join(line + "\n" for line in lines)
    sys.stdout.buffer.write(out.encode("utf-8", errors="surrogateescape"))
    sys.stdout.buffer.flush()


def main():
    lines = read_ledger(sys.argv[1])
    n = int(lines[0].split()[1])

    balances = {}
    for index in range(n):
        line = lines[1 + index].rstrip("\r")
        account, kind, amount = line.rsplit(" ", 2)
        if kind == "debit":
            sign = -1
        elif kind == "credit":
            sign = 1
        else:
            emit([f"ERROR line {index + 1}"])
            return
        balances[account] = balances.get(account, 0) + sign * to_cents(amount)

    ordered = sorted(
        balances.items(),
        key=lambda kv: (-kv[1], kv[0].encode("utf-8", errors="surrogateescape")),
    )
    out = [f"{account} {format_cents(balance)}" for account, balance in ordered]
    out.append(f"TOTAL {format_cents(sum(balances.values()))}")
    emit(out)


main()
